package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.phys.*;import net.minecraft.world.level.ClipContext;import net.minecraft.network.chat.Component;
/** Carries the existing robot entity. No duplicate item, inventory or replacement entity. */
public final class DeliveryGroundCargo{
 public static boolean loaded(DeliveryDroneEntity d){return d.getPassengers().stream().anyMatch(e->e instanceof VatagEntity);}
 private static boolean owner(DeliveryDroneEntity d,ServerPlayer p){var o=SbwCompat.resolveDroneOwner(p.serverLevel(),d);return o!=null&&DefenseData.allowed(p.serverLevel(),o.uuid(),o.name(),p);}
 public static boolean pickup(DeliveryDroneEntity d,Player player){if(!(player instanceof ServerPlayer p)||d.level()!=p.level()||!owner(d,p)||d.hasMountedExtractionCrate()||!d.getPassengers().isEmpty())return false;var l=p.serverLevel();var box=new AABB(d.getX()-2,d.getY()-4,d.getZ()-2,d.getX()+2,d.getY()+.5,d.getZ()+2);var candidates=l.getEntitiesOfClass(VatagEntity.class,box,r->!(r instanceof Wd01Entity)&&!(r instanceof Sd01Entity)&&(!(r instanceof SupplyRoverEntity rover)||rover.partner()==null)&&r.isAlive()&&!r.isWreck()&&!r.isPassenger()&&r.getPassengers().isEmpty()&&r.operator()==null&&r.permitted(p)&&r.getBbWidth()<=2.5&&r.getBbHeight()<=1.6&&r.getDeltaMovement().lengthSqr()<.04);candidates.sort(java.util.Comparator.comparingDouble(d::distanceToSqr));if(candidates.isEmpty())return false;var r=candidates.get(0);r.releaseControl();boolean ok=r.startRiding(d,true);if(ok)p.displayClientMessage(Component.translatable("delivery.robot_attached"),true);return ok;}
 public static boolean release(DeliveryDroneEntity d,Player player){if(!(player instanceof ServerPlayer p)||!owner(d,p))return false;var robot=d.getPassengers().stream().filter(e->e instanceof VatagEntity).findFirst().orElse(null);if(robot==null)return false;var l=p.serverLevel();Vec3 start=d.position(),end=start.add(0,-24,0);if(!Hgd01Lasers.loaded(l,start,end))return false;var hit=l.clip(new ClipContext(start,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,d));if(hit.getType()!=HitResult.Type.BLOCK)return false;var at=hit.getLocation().add(0,.02,0);var box=robot.getDimensions(Pose.STANDING).makeBoundingBox(at);if(!l.getWorldBorder().isWithinBounds(box)||!l.noCollision(robot,box)||!l.getEntities(robot,box,e->e!=d&&!e.isSpectator()&&!e.isPassenger()).isEmpty()){p.displayClientMessage(Component.translatable("delivery.robot_blocked"),true);return false;}robot.stopRiding();robot.setPos(at);robot.setXRot(0);robot.setDeltaMovement(Vec3.ZERO);if(robot instanceof VatagEntity r)r.setZRot(0);p.displayClientMessage(Component.translatable("delivery.robot_released"),true);return true;}
 public static void position(DeliveryDroneEntity d,Entity robot,Entity.MoveFunction move){var frame=Dd01VisualPose.matrix(d.getYaw(1),d.getBodyPitch(1),d.getRoll(1));var at=frame.transformPosition(new org.joml.Vector3d(0,.12,0));move.accept(robot,d.getX()+at.x,d.getY()+at.y,d.getZ()+at.z);robot.setYRot(d.getYaw(1));robot.setXRot(d.getBodyPitch(1));robot.setDeltaMovement(Vec3.ZERO);if(robot instanceof VatagEntity r)r.setZRot(d.getRoll(1));}
 private DeliveryGroundCargo(){}
}
